WITH exploded AS (SELECT id, effective_from, EXPLODE(discounts) AS val FROM price_tiers), scored AS (SELECT *, RANK() OVER (ORDER BY val NULLS FIRST) AS val_rank, CUME_DIST() OVER (ORDER BY val DESC) AS val_cume_dist, DENSE_RANK() OVER (ORDER BY val DESC NULLS LAST) AS val_dense_rank FROM exploded WHERE effective_from BETWEEN '2024-04-29' AND '2025-08-01'), enriched AS (SELECT id, effective_from, val_rank, CUME_DIST() OVER (ORDER BY val_cume_dist) AS val_cume_dist_cume_dist FROM scored), with_windows AS (SELECT effective_from, val_rank, DENSE_RANK() OVER (ORDER BY val_rank) AS val_rank_dense_rank, CUME_DIST() OVER (ORDER BY val_rank NULLS LAST) AS val_rank_cume_dist, RANK() OVER (ORDER BY val_cume_dist_cume_dist DESC NULLS LAST) AS val_cume_dist_cume_dist_rank, PERCENT_RANK() OVER w_grp AS val_cume_dist_cume_dist_percent_rank FROM enriched WINDOW w_grp AS (ORDER BY val_cume_dist_cume_dist NULLS LAST)), scored_price_tiers AS (SELECT *, CUME_DIST() OVER (ORDER BY val_rank) AS val_rank_cume_dist_2, PERCENT_RANK() OVER (ORDER BY val_cume_dist_cume_dist_percent_rank DESC NULLS LAST) AS val_cume_dist_cume_dist_percent_rank_percent_rank FROM with_windows) SELECT effective_from, val_rank, val_rank_cume_dist, val_cume_dist_cume_dist_rank, val_rank_cume_dist_2, val_cume_dist_cume_dist_percent_rank_percent_rank FROM scored_price_tiers ORDER BY val_rank DESC NULLS LAST
